/** @jsxImportSource react */

import { cn } from '@videojs/utils/style';
import type { ReactNode } from 'react';

import {
  Container as ContainerPrimitive,
  Poster as PosterPrimitive,
  Slider as SliderPrimitive,
} from '../../skin-primitives';
import { ErrorDialog } from '../shared/skins/scaffold/shared/error-dialog';
import { Indicators } from '../shared/skins/scaffold/shared/indicators';
import { SeekIndicator } from '../shared/skins/scaffold/shared/seek-indicator';
import { StatusAnnouncer } from '../shared/skins/scaffold/shared/status-announcer';
import { Poster } from '../shared/skins/scaffold/shared/video-feedback';
import { VideoGestures } from '../shared/skins/shared/video/behaviors/gestures';
import { VideoHotkeys } from '../shared/skins/shared/video/behaviors/hotkeys';
import { VideoControls } from './controls';

export interface VideoSkinProps extends Omit<ContainerPrimitive.Props, 'children'> {
  children?: ReactNode;
  renderPoster?: PosterPrimitive.ImageProps['render'];
  renderThumbnail?: SliderPrimitive.Thumbnail.ImageProps['render'];
}

export function VideoSkin({ children, className, renderPoster, renderThumbnail, ...props }: VideoSkinProps = {}) {
  return (
    <ContainerPrimitive
      className={cn('media-skin', 'media-container', 'media-video', className)}
      data-theme="scaffold"
      data-preset="video"
      {...props}
    >
      {children}
      <Poster renderImage={renderPoster} />
      <ErrorDialog />
      <VideoControls renderThumbnail={renderThumbnail} />

      <VideoHotkeys />
      <VideoGestures />
      <StatusAnnouncer />
      <Indicators>
        <SeekIndicator />
      </Indicators>
    </ContainerPrimitive>
  );
}
